"""Generation 5: improves EMAIL precision and recall by supporting plus signs in usernames and tightening boundary matching."""
import re

PATTERNS = [
    # Email: standard and obfuscated, supporting plus signs and strict trailing boundaries
    ("EMAIL", re.compile(
        r"""[\w.-]+(?:\+[\w.-]*)?(?:\s*\[at\]\s*|\s*@\s*)[\w.-]+(?:\s*\[dot\]\s*|\s*\.\s*)[a-zA-Z]{2,}\b""",
        re.IGNORECASE
    )),
    # Phone: US and international formats with clearer structural boundaries to avoid order numbers
    ("PHONE", re.compile(r"""(?:
        (?:\+?\d{1,3}\s*)?\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}
      | \+\d{1,3}\s+\d{1,4}\s+\d{3,4}\s+\d{3,4}
      | (?:phone|tel|cell|mobile|call(?:\s+me)?(?:\s+at)?)[:\s]+(?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}(?:\s*(?:ext|x)\s*\d+)?
    )""", re.IGNORECASE | re.VERBOSE)),
    # SSN: 3-2-4 digits with hyphens or spaces
    ("SSN", re.compile(r"\b\d{3}[-\s]\d{2}[-\s]\d{4}\b")),
    # Credit Card: 13-19 digits with optional spaces or dashes
    ("CREDIT_CARD", re.compile(r"\b(?:\d[ -]*){13,19}\b")),
    # ADDRESS: US street address through ZIP code, optionally spanning a newline
    ("ADDRESS", re.compile(r"\b\d{1,6}\s+[A-Za-z0-9#.,\s-]+(?:Apt\.?|Suite|Unit|Ste\.?)\s*\d+[A-Za-z0-9#.,\s-]*,?\s+[A-Za-z\s]+,\s+[A-Z]{2}\s+\d{5}(?:-\d{4})?\b|\b\d{1,6}\s+[A-Za-z0-9#.,\s-]+[\s,]+[A-Za-z\s]+[\s,]+[A-Z]{2}\s+\d{5}(?:-\d{4})?\b")),
